export function openForecastReview({source,map,data,weakWalls=[],adjusted=0,sections=1,onApply,onDiscard}){
 const dialog=document.querySelector('#dialog');if(!dialog)return;
 dialog.className='ai-review-dialog';dialog.innerHTML=`<header class="dialog-header"><div><h2 id="dialog-title">Review forecast walls</h2><p>${data.walls.length} walls · ${data.doors.length} doors · ${sections} scan sections</p></div><button type="button" class="icon-button" data-forecast-discard aria-label="Discard forecast">×</button></header><div class="dialog-content"><p>Walls are red, doors cyan, vertices white. Orange lines have weak image support—inspect them closely. Existing walls stay unchanged until you apply this draft.</p><p>${adjusted?adjusted+' wall lines received small image alignment corrections. ':''}${weakWalls.length?weakWalls.length+' lines need closer review.':'Check missing walls, corridors and doorways before applying.'}</p><div class="forecast-review-controls"><label>Zoom<input type="range" min="100" max="500" value="100" data-forecast-zoom></label><label><input type="checkbox" data-forecast-vertices checked> Show vertices</label></div><div class="forecast-review-viewport" tabindex="0" aria-label="Forecast map preview; scroll to inspect"><canvas aria-label="Generated walls over map artwork"></canvas></div><p role="status" class="forecast-review-status"></p><div class="ai-forecast-dialog-actions"><button type="button" class="button outline" data-forecast-discard>Discard draft</button><button type="button" class="button primary" data-forecast-apply>Apply & edit walls</button></div></div>`;
 const cancelled=()=>onDiscard?.();dialog.addEventListener('cancel',cancelled);dialog.addEventListener('close',()=>dialog.removeEventListener('cancel',cancelled),{once:true});
 const canvas=dialog.querySelector('canvas'),viewport=dialog.querySelector('.forecast-review-viewport'),context=canvas.getContext('2d'),scale=Math.min(1,3072/Math.max(map.width,map.height));canvas.width=Math.round(map.width*scale);canvas.height=Math.round(map.height*scale);
 function draw(){context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(source,0,0,canvas.width,canvas.height);const vertices=dialog.querySelector('[data-forecast-vertices]').checked;for(const [kind,color]of [['walls','#ff4163'],['doors','#00e4ed']])for(const [index,line]of data[kind].entries()){
  const x1=(line.x1*(map.cellWidth??map.size)+(map.offsetX??0))*scale,y1=(line.y1*(map.cellHeight??map.size)+(map.offsetY??0))*scale,x2=(line.x2*(map.cellWidth??map.size)+(map.offsetX??0))*scale,y2=(line.y2*(map.cellHeight??map.size)+(map.offsetY??0))*scale;context.strokeStyle=kind==='walls'&&weakWalls.includes(index)?'#ffb63f':color;context.lineWidth=3.5;context.beginPath();context.moveTo(x1,y1);context.lineTo(x2,y2);context.stroke();if(vertices)for(const [x,y]of [[x1,y1],[x2,y2]]){context.fillStyle='#fff';context.strokeStyle='#152c23';context.lineWidth=1.5;context.beginPath();context.arc(x,y,3.5,0,Math.PI*2);context.fill();context.stroke();}
 }}
 const zoom=dialog.querySelector('[data-forecast-zoom]');function resize(){const fit=Math.min(viewport.clientWidth/canvas.width,viewport.clientHeight/canvas.height);canvas.style.width=Math.round(canvas.width*fit*Number(zoom.value)/100)+'px';canvas.style.height='auto';}
 zoom.addEventListener('input',resize);dialog.querySelector('[data-forecast-vertices]').addEventListener('change',draw);
 for(const button of dialog.querySelectorAll('[data-forecast-discard]'))button.addEventListener('click',()=>{dialog.close();onDiscard?.();});
 dialog.querySelector('[data-forecast-apply]').addEventListener('click',async event=>{const button=event.target;button.disabled=true;try{if(await onApply()===false)throw Error('The forecast could not be applied.');dialog.close();}catch(error){dialog.querySelector('.forecast-review-status').textContent=error.message;}finally{button.disabled=false;}});
 if(!dialog.open)dialog.showModal();draw();resize();
}
